const rpgProfiles={
 research:['佐藤葵','研發主管','林祐','研發工程師','專案路線、停損與失敗風險'],process:['陳禾','製程主管','吳晶','良率工程師','製程版本、技術使用與良率'],scale:['陳禾','產能廠長','林穗','採購經辦','稼動率、訂量承諾與成本節省'],brand:['Alex','市場主管','Maya','通路經理','推廣決策、經銷權與支出'],lrd:['Noor','經銷主管','Lars','倉儲主管','備貨、信用與跌價來源'],dempe:['林安','技術策略主管','佐藤葵','技術專家','DEMPE、人員與控制'],methods:['林安','交易主管','陳禾','製造業務經辦','交易條款、可比較價格與獨特貢獻'],comparables:['Alex','銷售主管','Maya','營運分析師','受測個體、分部與可比差異'],documents:['林安','營運主管','陳雨','檔案管理員','交易範圍及申報勾稽'],services:['林安','服務主管','陳雨','IT 使用者','實際交付與效益'],cca:['佐藤葵','共同研發負責人','林祐','技術工程師','權利、預期利益與貢獻價值'],restructure:['陳禾','重組專案主管','吳晶','移轉作業人員','移轉標的及實際可得選項'],finance:['Aoife','資金主管','Liam','融資經辦','還款能力、信用與貸款條款'],map:['阿芬','協商聯絡員','王衡','跨境稅務經辦','調整期間、協定及對應認定'],sandwich:['Aoife','授權鏈主管','Liam','權利金經辦','適用年度、居住者與權利金'],bbformula:['陳禾','電子化學液製造主管','吳晶','配方製程工程師','BB原液定價、秘密配方、DEMPE與可比方法'],htvi:['佐藤葵','技術估值主管','林祐','預測編製人員','事前資訊、機率與未來結果'],amountb:['Noor','經銷主管','Lars','分部經辦','適用範圍、活動分離與門檻'],location:['陳禾','營運主管','林穗','採購經辦','當地市場、成本及議價選項'],guarantee:['Aoife','融資主管','Liam','銀行往來經辦','明示保證與增量效益'],cashpool:['Aoife','資金池主管','Liam','結算經辦','池主功能、餘額期間與綜效']};
const docTypes={contract:'關係企業合約',decision:'決策／授權／往來紀錄',ledger:'總帳、分部損益及交易橋接',capacity:'事前財務能力與資金資料',counter:'企業反證與支持附件'};
let rpgTab='field',talkRole=null,docViewing=null,noticeDraft=null,lastRPGRecord=null;
function stateRPG(s){if(!s.rpg||s.rpg.universe!==s.universe){s.rpg=TPRPG.create();s.rpg.universe=s.universe}s.rpg.requiresCapacity=['research','lrd','dempe','finance','cca','cashpool'].includes(activeCase);return s.rpg}
function currentRPG(){const c=mysteries.find(c=>c.id===activeCase),s=entry(c.id);return {c,s,r:stateRPG(s),w:c.worlds[s.universe]}}
function gameClock(r){return `${String(9+Math.floor(r.clock/6)).padStart(2,'0')}:${String(r.clock%6*10).padStart(2,'0')}`}
function witnesses(c){const p=rpgProfiles[c.id];return [
 {id:'chief',name:p[0],role:p[1],face:c.island===2?'👩🏻‍🔬':'🧑🏻‍💼',scope:p[4],source:'決策層'},
 {id:'staff',name:p[2],role:p[3],face:'👨🏻‍🔧',scope:'親自執行的步驟與文件來源',source:'現場層'},
 {id:'finance',name:'江予',role:'財務經理',face:'👩🏻‍💼',scope:'會計分錄、分部及資金資料',source:'帳務層'},
 {id:'taxpayer',name:'林安',role:'納稅人／集團 TP 代表',face:'🧑🏻‍💼',scope:'公司主張、交易背景與說明',source:'企業立場'},
 {id:'cpa',name:'周衡',role:'受託會計師',face:'👨🏻‍💼',scope:'報告依據、反證與方法限制',source:'專業意見'}]}
const oldRenderDistrict=renderDistrict;
renderDistrict=function(){const o=islands[explorer.island],list=localCases();$('#district').innerHTML=`<div class="district-rpg-head"><div><div class="eyebrow">${o.country} · 可步入的地點</div><h2>${o.name}</h2></div><button class="text-button" id="island-dossier">公司、職能與交易結構 ↗</button></div><div class="location-dock">${list.map(c=>`<button data-place="${c.id}"><span>${c.icon}</span><b>${c.place}</b><small>${entry(c.id)?.resolved?'✿ 已留足跡':entry(c.id)?'有待調查':'? 走近看看'}</small></button>`).join('')}${explorer.island===7?'<button id="consult-cpa"><span>📚</span><b>會計師辦公室</b><small>聽取主張與反證</small></button>':''}${explorer.island===6?'<button id="consult-tax"><span>🏛️</span><b>查核辦公室</b><small>程序、必要範圍與權利</small></button>':''}</div>`;document.querySelectorAll('[data-place]').forEach(e=>e.onclick=()=>openCase(e.dataset.place));$('#island-dossier').onclick=showCompany;if($('#consult-cpa'))$('#consult-cpa').onclick=openCPAOffice;if($('#consult-tax'))$('#consult-tax').onclick=showAuditLaw};
const originalWorldGo=goIsland;goIsland=function(i,travel=true){originalWorldGo(i,travel);window.TPScene?.focus(i);if(window.TPScene)window.scrollTo({top:0,behavior:'instant'})};drawWorldMap=function(){window.TPScene?.refresh()};
function openCPAOffice(){openModal('會計師事務所 · 周衡',`<div class="eyebrow">THE OTHER SIDE OF THE CASE</div><h2>📚 先替公司的說法，找最強的證據。</h2><p class="lead">「我的工作不只是反對調整，也要說清楚報告用什麼事實、哪些假設仍待確認。你可以選一件案卷，預約我訪談，核對反證與已取得的報酬。」</p><div class="journal-list">${knownCases().map(c=>`<button class="journal-entry" data-cpa-case="${c.id}"><span>${c.icon}</span><div><b>${c.title}</b><small>進入案卷，安排會計師訪談</small></div></button>`).join('')}</div><p class="lead small-lead">這是虛構 RPG 顧問。意見不是裁判；與當事人有利或不利的證據都要查證。</p>`);document.querySelectorAll('[data-cpa-case]').forEach(e=>e.onclick=()=>{openCase(e.dataset.cpaCase);stateRPG(entry(e.dataset.cpaCase)).tab='interviews';stateRPG(entry(e.dataset.cpaCase)).npc='cpa';renderCase()})}window.openCPAOffice=openCPAOffice;
renderCase=function(){const {c,s,r,w}=currentRPG();if(lastRPGRecord!==r){docViewing=null;noticeDraft=null;lastRPGRecord=r}rpgTab=r.tab||'field';const missing=TPRPG.ready(r);openModal('調查副本 · '+c.title,`<div class="rpg-case-heading"><div><div class="eyebrow">${c.era||'TP INVESTIGATION · ROLE PLAYING STORY'}</div><h2>${c.icon} ${c.title}</h2></div><div class="rpg-clock"><b>遊戲時間 ${gameClock(r)}</b><button id="advance-rpg-time">◷ 前進 10 分鐘</button></div></div><p class="rpg-rumor">${c.rumor}</p>${s.priorFinding?`<div class="rpg-prior">🌱 改善支線：前期例示調增所得 ${s.priorAmount} 的紀錄仍保留；本期重新查證。</div>`:''}<div class="rpg-tabs" role="tablist">${[['field','⌕','調查現場'],['interviews','♙','預約與訪談'],['documents','▤','合約與補充資料'],['audit','≋','帳務查核'],['position','⚖','提出主張']].map(([k,icon,t])=>`<button role="tab" aria-selected="${rpgTab===k}" data-rpg-tab="${k}" class="${rpgTab===k?'on':''}">${icon} ${t}</button>`).join('')}</div><div id="rpg-content">${rpgTab==='field'?fieldView(c,s,r):rpgTab==='interviews'?interviewView(c,s,r):rpgTab==='documents'?documentsView(c,s,r):rpgTab==='audit'?auditView(c,s,r):positionView(c,s,r)}</div><details class="case-codex"><summary>📖 案卷閱讀手冊 · OECD 索引、程序與史實</summary>${codex(c)}<div class="codex-inner">訪談不是測謊。以文據及不同來源核對陳述；矛盾不等於已證明故意說謊。臺灣程序參考 <a href="https://law-out.mof.gov.tw/LawContent.aspx?id=GL010325" target="_blank" rel="noopener">調查程序應行注意事項 ↗</a> 及 <a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340142" target="_blank" rel="noopener">納稅者權利保護法第 11–12 條 ↗</a>；不得逾課稅目的必要範圍，並注意有利與不利事項。遊戲時間與預約均為模擬，不會建立真實行事曆或寄送通知。</div></details><div class="case-exit"><button class="text-button" id="return-street">← 回到立體群島</button><span>訪談、通知、帳簿及人物均為教學情境。</span></div>`);
document.querySelectorAll('[data-rpg-tab]').forEach(b=>b.onclick=()=>{r.tab=b.dataset.rpgTab;saveWorld();renderCase()});$('#advance-rpg-time').onclick=()=>{TPRPG.advance(r);syncClues(s,r);saveWorld();renderCase();toast('遊戲時鐘前進，查看已到場人員與資料回覆。')};$('#return-street').onclick=()=>{$('#modal').close();goIsland(c.island,false)};
wireField(c,s,r);wireInterview(c,s,r);wireDocuments(c,s,r);wireAudit(c,s,r);wirePosition(c,s,r);updatePassport();saveWorld()};
function fieldView(c,s,r){return `<div class="rpg-field"><div class="field-visual"><span class="field-window">${islands[c.island].flag} ${islands[c.island].name}</span><div class="field-desk"></div><span class="field-plant">🪴</span><span class="field-person">${witnesses(c)[0].face}</span><button data-field-to="documents" class="field-contract">📄<b>桌上的合約</b><small>閱讀權利與責任</small></button><button data-field-to="interviews" class="field-npc">♙<b>員工座位</b><small>先預約，再問問題</small></button><button data-field-to="documents" class="field-mail">📬<b>補充說明櫃</b><small>調閱資料與回覆</small></button><button data-field-to="audit" class="field-ledger">📊<b>財務工作台</b><small>查帳、勾稽與排除重複</small></button></div><div class="field-mission"><div class="eyebrow">你的調查問題</div><h3>${c.question||'實際功能、控制風險與報酬，是否與合約一致？'}</h3><p>從不同職能聽到的說法可能只反映一部分。記錄原話、請對方舉例，再用資料反問。</p><div class="field-progress"><span>${r.docs.length} 份資料</span><span>${Object.keys(r.interviews).length} 位談話對象</span><span>${r.ledgerChecked?'✓ 已勾稽':'帳務待勾稽'}</span></div><button class="primary" data-field-to="interviews">先安排一場訪談 →</button></div></div>`}
function wireField(c,s,r){document.querySelectorAll('[data-field-to]').forEach(e=>e.onclick=()=>{r.tab=e.dataset.fieldTo;renderCase()})}
function interviewView(c,s,r){const list=witnesses(c),person=list.find(n=>n.id===r.npc);return `<div class="interview-layout"><div class="npc-list">${list.map(n=>{const booked=r.appointments[n.id]!==undefined,available=TPRPG.available(r,n.id),locked=n.id==='staff'&&!r.interviews.chief?.topics.includes('decision');return `<button data-npc="${n.id}" class="npc-card ${r.npc===n.id?'selected':''}"><span>${n.face}</span><div><b>${n.name} · ${n.role}</b><small>${n.id==='cpa'?'獨立會計師事務所':n.id==='taxpayer'?'總部／納稅人代表':islands[c.island].name} · ${locked?'先向主管確認流程，再約現場經辦':available?'● 已到場，可以開始':booked?'◷ 已預約，等待遊戲時段':n.source+' · 尚未預約'}</small></div></button>`}).join('')}<p class="sim-fine">預約及等待是遊戲時間。各人只陳述所知，職稱不等於控制風險。</p></div><div class="dialogue-panel">${person?personPanel(c,s,r,person):'<div class="dialogue-empty"><span>♙</span><h3>選一位員工，安排訪談。</h3><p>主管講授權，現場講執行，財務講入帳；會計師與納稅人代表提出另一種解釋。</p></div>'}</div></div>`}
function personPanel(c,s,r,n){const booked=r.appointments[n.id]!==undefined,available=TPRPG.available(r,n.id),locked=n.id==='staff'&&!r.interviews.chief?.topics.includes('decision'),v=r.interviews[n.id];if(locked)return `<div class="dialogue-empty"><span>${n.face}</span><h3>${n.name} · ${n.role}</h3><p>先向主管提出具體的決策流程問題，再請現場經辦就自己執行的部分說明。</p></div>`;if(!booked)return `<div class="appointment"><span>${n.face}</span><h3>預約 ${n.name} · ${n.role}</h3><p>訪談範圍：${n.scope}。</p><label>遊戲時段<select id="appointment-slot"><option value="1">下一時段 · 10 分鐘後</option><option value="2">稍晚時段 · 20 分鐘後</option></select></label><p class="sim-fine">可有代理人或輔佐人；記錄原話、確認更正。這不是正式調查通知。</p><button class="primary" id="book-npc">登錄模擬預約 →</button></div>`;if(!available)return `<div class="dialogue-empty"><span>◷</span><h3>訪談已預約。</h3><p>${n.name} 將於第 ${r.appointments[n.id]} 時段到場。目前是第 ${r.clock} 時段。</p><button class="primary" id="wait-npc">前進 10 分鐘 →</button></div>`;
const history=v?.history||[{who:'npc',text:opening(c,s,n)}];return `<div class="dialogue-person"><span>${n.face}</span><div><b>${n.name}</b><small>${n.role} · ${n.source}</small></div><i>${v?.discrepancy?'陳述落差待釐清':v?.topics.includes('cross')?'已作文件核對':'陳述待驗證'}</i></div><div class="dialogue-history" aria-live="polite">${history.slice(-6).map(h=>`<div class="speech-bubble ${h.who==='player'?'player':'npc'}"><small>${h.who==='player'?'你':n.name}</small><p>${safe(h.text)}</p></div>`).join('')}</div><button class="text-button transcript-button" id="full-transcript">▤ 查看完整訪談紀錄與原話</button><div class="dialogue-options">${questionOptions(c,s,r,n).map(q=>`<button data-question="${q.id}"><small>${q.tag}</small>${q.text}</button>`).join('')}</div>${v?.topics.includes('cross')?'<div class="dialogue-observation">🧷 已留下原話、資料及回應；仍須與其他來源核對，不以表情或語氣判定說謊。</div>':''}`}
function opening(c,s,n){if(n.id==='cpa')return '我是受託說明報告的會計師。請把企業最有利的證據也納入，不要只追著調增結論走。';if(n.id==='taxpayer')return '公司的正式立場是：交易有契約依據。我們希望你先了解商業背景及已獲得的報酬，再判斷。';if(n.id==='finance')return '我可以解釋入帳及分部，但帳上承擔損失，不一定代表會計部門決定風險。';if(n.id==='staff')return '我只能說明自己做過的事。有人說「我們負責」，有時指執行，有時才是有權作決定。';return ({research:'我們就是受託研發，重要路線都由總部決定，我們只是執行。',process:'我們只是依照總部配方製造，沒有額外技術需要另外報酬。',lrd:'我們叫有限風險經銷商，所以庫存損失都應由總部補。',scale:'成本降低都是集團規模帶來的，所以利益應由總部取得。'}[c.id]||'合約安排都有依據，我們的報酬也都合理。你想核對哪一段流程？')}
function questionOptions(c,s,r,n){const v=r.interviews[n.id]||{topics:[]},specific=v.topics.includes('open');if(v.needsRepair)return [{id:'repair',tag:'重新表述',text:'先不下定論，請逐項說明紀錄與陳述不同的原因。'},{id:'finish',tag:'保留待查',text:'先保留原話與異議，待補充資料後再談。'}];let q=[{id:'open',tag:'開放式',text:'請從提案到執行，說明你親自參與的流程。'}];if(specific)q.push({id:'decision',tag:'具體追問',text:'最近一次改變或否決決定，是誰提出、誰能拍板？'},{id:'example',tag:'追溯文件',text:'請指出人員、一次具體事件及可以核對的文件。'});if(n.id==='finance'&&specific)q.push({id:'capacity',tag:'財務追問',text:'帳務承擔與事前財務能力，分別有什麼資料？'});if((n.id==='cpa'||n.id==='taxpayer')&&specific)q.push({id:'counter',tag:'企業反證',text:'對目前疑點，企業最強的另一種解釋是什麼？'});if(specific)q.push({id:'cross',tag:'拿資料反問',text:r.docs.includes('decision')?'把決策及授權紀錄放在桌上，請對照剛才的說法。':'拿目前已有的合約，請對照實際執行。'},{id:'accuse',tag:'測試問法',text:'所以你們全部都是虛假安排，對不對？'});return q}
function wireInterview(c,s,r){document.querySelectorAll('[data-npc]').forEach(e=>e.onclick=()=>{r.npc=e.dataset.npc;renderCase()});const n=witnesses(c).find(n=>n.id===r.npc);if(!n)return;if($('#full-transcript'))$('#full-transcript').onclick=()=>{const v=r.interviews[n.id];openModal('訪談紀錄 · '+n.name,`<h2>${n.face} ${n.name} · ${n.role}</h2><p class="lead small-lead">本案：${c.title}。原話與更正並存，陳述待證據核對；這是虛構教學紀錄。</p><div class="dialogue-history full-history">${(v?.history||[{who:'npc',text:opening(c,s,n)}]).map(h=>`<div class="speech-bubble ${h.who==='player'?'player':'npc'}"><small>${h.who==='player'?'調查員':n.name}</small><p>${safe(h.text)}</p></div>`).join('')}</div><button class="primary" id="back-from-transcript">回到訪談 →</button>`);$('#back-from-transcript').onclick=renderCase};if($('#book-npc'))$('#book-npc').onclick=()=>{r.appointments[n.id]=r.clock+Number($('#appointment-slot').value);saveWorld();renderCase()};if($('#wait-npc'))$('#wait-npc').onclick=()=>{$('#advance-rpg-time').click()};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>askQuestion(c,s,r,n,b.dataset.question,b.textContent.trim()))}
function askQuestion(c,s,r,n,q,text){const w=c.worlds[s.universe];if(!r.interviews[n.id])r.interviews[n.id]={topics:[],history:[{who:'npc',text:opening(c,s,n)}]};const v=r.interviews[n.id];v.history.push({who:'player',text});let answer='';if(q==='open'){answer=n.id==='finance'?`我處理的是這些數據：${w.clues[2]} 但仍要核對總帳、期間、分部和已補償部分。`:n.id==='cpa'||n.id==='taxpayer'?`請先保留這個事實：${w.clues[0]}`:`我的工作與 ${rpgProfiles[c.id][4]} 有關。合約安排是：${w.clues[0]}`}
else if(q==='decision'){answer=n.id==='chief'&&c.id==='research'&&s.universe===1?'最近一次路線有改變，最後文件確實有總部簽名。但簽名前誰提案、誰能停止，我需要把會議及版本紀錄調出來再確認。':n.id==='finance'?`我不把會計分錄當作拍板證據。就本案可核對的決策資料而言：${w.clues[1]}`:n.id==='staff'?`就執行過程我能確認：${w.clues[1]} 我所知的範圍仍須和主管說明分開記錄。`:`具體情況是：${w.clues[1]}`}
else if(q==='example'){answer=`請調閱本案決策／授權／往來紀錄，並與人員職責、實際執行及財務紀錄核對。不能只憑我一句「總部負責」就確認。現有線索為：${w.clues[1]}`}
else if(q==='capacity'){answer=`要分開看事前可得資金與事後誰入帳。與本案相關的記錄是：${w.clues[1]}；帳務則是：${w.clues[2]}。未記載的資金數據不能自行補成有財務能力。`}
else if(q==='counter'){answer=`企業提出的反證或需要排除的另一種解釋是：${w.clues[3]}。請明確回應，不要把異議本身當成不合作。`}
else if(q==='cross'){if(r.docs.includes('decision')){v.discrepancy=n.id==='chief'&&(['research','process'].includes(c.id)&&s.universe!==0||c.id==='lrd'&&s.universe!==0);answer=`我補充並確認：${w.clues[1]}。請把「依合約安排」與「實際作決定」的差異寫入紀錄；如果先前用詞太概括，應註明更正原因。這份核對本身並不證明誰故意說謊。`;}else{answer='目前只有合約約定，還不足以核對實際決策。請調閱決策、授權與往來紀錄後再追問；本次不記為已完成文件核對。';q='contract-only'}}
else if(q==='accuse'){v.needsRepair=true;answer='這個問法已預設全部虛假。我不同意這樣概括記錄，請分開問具體行為、資料與差異，也請保留我的異議。'}
else if(q==='repair'){v.needsRepair=false;answer=`謝謝重新表述。就具體差異而言，請一併考慮：${w.clues[3]}。我們可以回到可核對的事件及紀錄。`}
else if(q==='finish'){v.needsRepair=false;answer='請把目前未釐清部分及我的原話一併保留，待收到資料後可以續談。'}
if(!v.topics.includes(q))v.topics.push(q);v.history.push({who:'npc',text:answer.replace(/。。/g,'。')});syncClues(s,r);saveWorld();renderCase()}
function documentsView(c,s,r){return `<div class="documents-layout"><div class="document-shelf"><h3>📂 本案資料櫃</h3>${Object.entries(docTypes).map(([k,t])=>`<button data-read-doc="${k}" ${k!=='contract'&&!r.docs.includes(k)?'disabled':''}><span>${r.docs.includes(k)?'●':'○'}</span><div><b>${t}</b><small>${k==='contract'?'可直接閱讀':r.docs.includes(k)?'已收到 · 點開核對':'須以補充資料通知調閱'}</small></div></button>`).join('')}<h4>模擬通知及回覆</h4>${r.requests.map((q,i)=>`<p class="request-status">${q.status==='received'?'✓ 已回覆':'◷ 等待回覆'} · 第 ${i+1} 份<br><small>${q.docs.map(k=>docTypes[k]).join('、')}</small></p>`).join('')||'<p class="sim-fine">尚未登錄補充資料通知。</p>'}</div><div class="notice-workbench">${docViewing?readDoc(c,s,r,docViewing):noticeDraft?noticePreview(c,r):noticeForm(c,r)}</div></div>`}
function readDoc(c,s,r,k){const w=c.worlds[s.universe],i={contract:0,decision:1,ledger:2,counter:3,capacity:1}[k];return `<div class="document-paper"><div class="eyebrow">FICTIONAL CASE RECORD · ${docTypes[k]}</div><h3>${c.title}</h3><p>${w.clues[i]}</p>${k==='capacity'?'<p class="sim-fine">此項只重列案卷中與能力、風險或資力相關的既有事實；原案沒有的銀行數字不自行填入。仍不足時應保留補查。</p>':''}<div class="paper-stamp">教學假設<br>非真實文據</div></div><button class="choice" id="back-notice">返回補充資料工作台 →</button>`}
function noticeForm(c,r){return `<h3>發補充說明，先說清楚要驗證什麼。</h3><p class="lead small-lead">範圍與目的須相稱。不要一次要求與本案無關的所有私人資訊。</p><label>調查範圍<select id="request-scope"><option value="transaction">本案受控交易、所涉期間與相關人員職務</option><option value="all">整個集團所有私人訊息及無關帳冊</option></select></label><fieldset><legend>需要哪些資料？</legend>${Object.entries(docTypes).filter(([k])=>k!=='contract').map(([k,t])=>`<label class="check-doc"><input type="checkbox" name="request-doc" value="${k}" ${(['decision','ledger','counter'].includes(k)||k==='capacity'&&r.requiresCapacity)?'checked':''}>${t}</label>`).join('')}</fieldset><label>具體要釐清的事實<textarea id="request-purpose" rows="3" placeholder="例如：核對本案重大決策是否由契約所載一方實際執行，及分部報酬是否已反映相關風險。"></textarea></label><div id="request-error" class="request-error" role="status"></div><button class="primary" id="preview-request">整理模擬通知草稿 →</button><p class="sim-fine">不寄信、不送出公文；對象及期限僅為遊戲設定。實際調查另依適用法令、必要範圍及權利保障辦理。</p>`}
function noticePreview(c,r){return `<div class="document-paper"><div class="eyebrow">IN-GAME NOTICE · 教學草稿</div><h3>請就本案交易提供補充說明及資料</h3><p><b>受理案：</b>${c.title}<br><b>範圍：</b>本案所涉受控交易、年度及相關職能；非全體私人訊息。</p><p><b>待釐清事實：</b>${safe(noticeDraft.purpose)}</p><ol>${noticeDraft.docs.map(k=>`<li>${docTypes[k]}，請說明與本案交易的關聯，並提供勾稽方式。</li>`).join('')}</ol><p>請保留企業說明及反證；需要釐清範圍時，可先提出說明。遊戲資料於下一時段回覆。</p><p class="sim-fine">正式通知的法令依據、對象、期間、必要性與程序權利需另依真實案件填列，此處不作真實公文使用。</p></div><div class="choice-row"><button class="primary" id="register-request">登錄模擬通知，等待回覆 →</button><button class="choice" id="edit-request">返回修改</button></div>`}
function wireDocuments(c,s,r){document.querySelectorAll('[data-read-doc]').forEach(e=>e.onclick=()=>{docViewing=e.dataset.readDoc;if(docViewing==='contract'&&!r.docs.includes('contract'))r.docs.push('contract');syncClues(s,r);saveWorld();renderCase()});if($('#back-notice'))$('#back-notice').onclick=()=>{docViewing=null;renderCase()};if($('#preview-request'))$('#preview-request').onclick=()=>{const docs=[...document.querySelectorAll('[name="request-doc"]:checked')].map(e=>e.value),purpose=$('#request-purpose').value,scope=$('#request-scope').value,probe=TPRPG.create(),result=TPRPG.request(probe,docs,purpose,scope);if(!result.ok){$('#request-error').textContent=result.error;return}noticeDraft={docs,purpose,scope};renderCase()};if($('#register-request'))$('#register-request').onclick=()=>{TPRPG.request(r,noticeDraft.docs,noticeDraft.purpose,noticeDraft.scope);noticeDraft=null;saveWorld();renderCase();toast('已登錄遊戲通知。前進 10 分鐘可查看回覆。')};if($('#edit-request'))$('#edit-request').onclick=()=>{noticeDraft=null;renderCase()}}
function auditView(c,s,r){const w=c.worlds[s.universe];if(!r.docs.includes('ledger'))return `<div class="audit-empty"><span>📊</span><h3>帳務工作台還缺少資料。</h3><p>先向財務經理訪談，並以補充資料通知取得總帳、分部損益與交易橋接。</p><button class="primary" id="audit-request-docs">前往補充資料工作台 →</button></div>`;return `<div class="audit-workbench"><div><div class="eyebrow">FOLLOW THE TRANSACTION, NOT JUST THE MARGIN</div><h3>從合約走到帳，再走回真正的交易。</h3><table><tr><th>查核環節</th><th>本案要核對什麼</th></tr><tr><td>原始依據</td><td>${w.clues[0]}</td></tr><tr><td>交付／決策</td><td>${r.docs.includes('decision')?w.clues[1]:'決策資料尚未調回，不得自行填入。'}</td></tr><tr><td>帳載與分部</td><td>${w.clues[2]}</td></tr><tr><td>反證／已補償部分</td><td>${r.docs.includes('counter')?w.clues[3]:'企業反證尚未收到，請先調閱。'}</td></tr></table><div class="note">先排除期間、科目分類、匯差、分部範圍與重複計酬；帳面損失不自動代表風險歸屬。</div></div><div class="audit-calculator"><b>本案差額勾稽</b><p>依案卷明列的教學假設，計算尚未被反映的例示所得差額。補稅仍須先支持方法、事實與程序。</p><div class="audit-formula">${w.formula}</div><label>${c.taxKind==='group'?'雙邊淨等值所得差額':'本案例示所得差額'}<input id="audit-amount" type="number" min="0" step="0.01" placeholder="填入你的勾稽結果"></label><button class="primary" id="check-ledger">核對勾稽結果 →</button><div id="ledger-feedback" aria-live="polite">${r.ledgerChecked?'✓ 本期差額已核對；不代表已完成核定。':''}</div></div></div>`}
function wireAudit(c,s,r){if($('#audit-request-docs'))$('#audit-request-docs').onclick=()=>{r.tab='documents';docViewing=null;renderCase()};if($('#check-ledger'))$('#check-ledger').onclick=()=>{const raw=$('#audit-amount').value,n=Number(raw),w=c.worlds[s.universe];if(raw!==''&&Number.isFinite(n)&&Math.abs(n-w.amount)<.001){r.ledgerChecked=true;saveWorld();$('#ledger-feedback').textContent='✓ 與本案假設勾稽一致。仍需聽取反證、支持方法並完成程序。'}else $('#ledger-feedback').textContent='差額尚未接上。請重新檢查公式、已補償部分與是否重複計入；這裡不是填總稅額。'}}
function positionView(c,s,r){const missing=TPRPG.ready(r);return `<div class="position-layout"><div><div class="eyebrow">A POSITION YOU CAN EXPLAIN</div><h3>你的主張，要能回應另一方的故事。</h3><div class="position-checks">${[['讀合約',r.docs.includes('contract')],['查決策紀錄',r.docs.includes('decision')],['收帳務資料',r.docs.includes('ledger')],['注意企業反證',r.docs.includes('counter')],['帳務已勾稽',r.ledgerChecked]].map(([t,ok])=>`<span class="${ok?'ok':''}">${ok?'✓':'○'} ${t}</span>`).join('')}</div><label class="hypothesis-label">初步分析主張<select id="rpg-theory"><option value="">先選擇主張</option>${c.worlds.map((w,i)=>`<option value="${i}" ${s.theory===i?'selected':''}>${String.fromCharCode(65+i)} · ${w.finding}</option>`).join('')}<option value="more" ${s.theory==='more'?'selected':''}>仍有關鍵疑點，先補查</option></select></label><label class="rpg-notes-label">推理與待查事項（此瀏覽器暫存）<textarea id="rpg-note" rows="4" placeholder="事實 → 證據 → 企業主張與反證 → 方法 → 所得差額">${safe(s.note)}</textarea></label><button class="primary" id="submit-rpg-position">檢驗主張，走向本案結局 →</button>${s.resolved?'<button class="choice" id="rpg-existing-ending">查看已完成的平行結局 ↗</button>':''}</div><aside class="position-review"><b>查核卷宗的完整度</b>${missing.length?`<ul>${missing.map(m=>`<li>${m}</li>`).join('')}</ul>`:'<p>已完成本遊戲的資料、具體訪談與勾稽條件。這不是 OECD 認證或真實案件充分證據保證。</p>'}<p>不從表情猜測誠信，不把財務紀錄等同決策權，不因補稅就自動認定違章。</p></aside></div>`}
function wirePosition(c,s,r){if($('#rpg-theory'))$('#rpg-theory').onchange=e=>{s.theory=e.target.value==='more'?'more':e.target.value===''?null:Number(e.target.value);saveWorld()};if($('#rpg-note'))$('#rpg-note').oninput=e=>{s.note=e.target.value;saveWorld()};if($('#rpg-existing-ending'))$('#rpg-existing-ending').onclick=()=>showEnding(c,s);if($('#submit-rpg-position'))$('#submit-rpg-position').onclick=()=>{const missing=TPRPG.ready(r);if(s.theory!=='more'&&missing.length){toast('卷宗還缺：'+missing[0]);return}syncClues(s,r);submitTheory(c,s)}}
function syncClues(s,r){const pairs={contract:0,decision:1,ledger:2,counter:3};for(const k of r.docs){let i=pairs[k];if(i!==undefined&&!s.clues.includes(i))s.clues.push(i)}}
const oldOpenCase=openCase;openCase=function(id){const changing=activeCase!==id;activeCase=id;discover(id);if(changing){docViewing=null;noticeDraft=null}renderCase();updatePassport()};
$('#guide').onclick=()=>openModal('小芽的立體群島指南',`<h2>🕵️ 這一次，走進公司裡面。</h2><p class="lead">拖曳旋轉群島、滾輪縮放；點公司走近，再點建築名牌或下方地點進入副本。</p><div class="guide-route"><span>📄 看合約</span><span>♙ 約訪員工</span><span>🗣 分支問答</span><span>📬 模擬補充說明</span><span>📊 查帳勾稽</span><span>⚖ 主張與平行結局</span></div><div class="note">預約會推進遊戲時鐘，不建立真實行事曆。問主管決策、問員工執行、問財務帳務，也要聽會計師與納稅人的反證。發現陳述落差後，拿文件追問；沒有測謊分數。</div><p class="lead">原有 21 件事件與 63 條事實時間線全部保留。立體場景與 NPC 問答均為原創規則式模擬，未串接生成式 AI。</p>`);
renderDistrict();

document.querySelector('.brand').onclick=e=>{e.preventDefault();window.scrollTo({top:0,behavior:'instant'});window.TPScene?.home()};
